import sys
from collections import deque

def maximumMatch(G):
    if not G:
        return 0

    M = len(G)
    N = len(G[0]) if M > 0 else 0

    # match[j] stores the applicant assigned to job j
    match = [-1] * N

    def dfs(u, visited):
        for v in range(N):
            if G[u][v] == 1 and not visited[v]:
                visited[v] = True
                if match[v] < 0 or dfs(match[v], visited):
                    match[v] = u
                    return True
        return False

    result = 0
    for i in range(M):
        visited = [False] * N
        if dfs(i, visited):
            result += 1

    return result

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        M = int(next(iterator))
        N = int(next(iterator))

        G = []
        for _ in range(M):
            row = []
            for _ in range(N):
                row.append(int(next(iterator)))
            G.append(row)

        ans = maximumMatch(G)
        print(ans)
    except StopIteration:
        pass

if __name__ == "__main__":
    main()
